// Tests of the part tools on the fixture (test/fixtures/test-board.step, generated by tools/c3dparts/tests/fixture.py).
// The expected values are the outputs of the Python reference implementation (tools/c3dparts), kept in
// test/fixtures/*.reference.json, so these tests need no Python.
//   npm test
import assert from 'node:assert/strict';
import {copyFileSync, mkdtempSync, readFileSync, rmSync, statSync, writeFileSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {dirname, join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {after, before, describe, test} from 'node:test';
import {main} from '../cli.ts';
import type {Part} from './convert.ts';
import {inspect} from './inspect.ts';
import {loadSpec, SpecError} from './spec.ts';
import {readStep, StepReadError} from './step.ts';

const FIXTURES = join(dirname(fileURLToPath(import.meta.url)), 'test', 'fixtures');
const reference = (name: string): unknown => JSON.parse(readFileSync(join(FIXTURES, `test-board.${name}.reference.json`), 'utf8'));

/** Deep comparison where numbers may differ by `tolerance`. */
function assertClose(actual: unknown, expected: unknown, tolerance = 0.002, path = ''): void {
  if (typeof expected === 'number') {
    assert.ok(typeof actual === 'number', `${path}: number expected`);
    assert.ok(Math.abs(actual - expected) <= tolerance, `${path}: ${actual} instead of ${expected}`);
  } else if (Array.isArray(expected)) {
    assert.ok(Array.isArray(actual) && actual.length === expected.length, `${path}: array of ${expected.length} expected`);
    expected.forEach((v, i) => assertClose(actual[i], v, tolerance, `${path}[${i}]`));
  } else if (expected && typeof expected === 'object') {
    assert.ok(actual && typeof actual === 'object', `${path}: object expected`);
    const a = actual as Record<string, unknown>, e = expected as Record<string, unknown>;
    assert.deepEqual(Object.keys(a).sort(), Object.keys(e).sort(), `${path}: keys`);
    for (const k of Object.keys(e)) assertClose(a[k], e[k], tolerance, `${path}.${k}`);
  } else {
    assert.equal(actual, expected, path);
  }
}

describe('inspect', () => {
  test('matches the Python reference on the fixture', async () => {
    assertClose(inspect(await readStep(join(FIXTURES, 'test-board.step'))), reference('inspect'));
  });

  test('a missing file is reported', async () => {
    await assert.rejects(readStep(join(FIXTURES, 'missing.step')), StepReadError);
  });
});

describe('convert', () => {
  let folder: string, code: number, component: {format: string; version: number; part: Part};
  before(async () => {
    folder = mkdtempSync(join(tmpdir(), 'parts-test-'));
    for (const file of ['part.yaml', 'test-board.step']) copyFileSync(join(FIXTURES, file), join(folder, file));
    code = await main(['part', 'convert', join(folder, 'part.yaml')], {out: () => {}})
    component = JSON.parse(readFileSync(join(folder, 'test-board.c3dcomponent'), 'utf8'));
  });
  after(() => rmSync(folder, {recursive: true, force: true}));

  test('writes the component and the preview', () => {
    assert.equal(code, 0);
    assert.equal(component.format, 'c3d-component');
    assert.equal(component.version, 1);
    assert.equal(Buffer.from(component.part.asset, 'base64').subarray(0, 4).toString(), 'glTF');
    assert.ok(statSync(join(folder, 'test-board.png')).size > 10_000);
  });

  test('matches the Python reference on the fixture', () => {
    const {asset, ...part} = component.part;
    assertClose(part, reference('convert'));
  });
});

describe('spec errors', () => {
  let folder: string;
  before(() => { folder = mkdtempSync(join(tmpdir(), 'parts-spec-')); });
  after(() => rmSync(folder, {recursive: true, force: true}));
  const load = (text: string) => {
    const file = join(folder, 'part.yaml');
    writeFileSync(file, text);
    return () => loadSpec(file);
  };
  const pin = 'pins: [{id: A, at: [0,0,0], exit: [0,0,1]}]';

  test('id must be kebab-case', () => {
    assert.throws(load(`id: Test Board\nname: x\nstep: a.step\n${pin}`), {name: 'Error', message: /kebab-case/});
  });
  test('pin ids must be unique', () => {
    assert.throws(load('id: t\nname: x\nstep: a.step\npins:\n  - {id: A, at: [0,0,0], exit: [0,0,1]}\n'
      + '  - {id: A, at: [1,0,0], exit: [0,0,1]}'), /duplicate/);
  });
  test('colours must be in the palette or #rrggbb', () => {
    assert.throws(load(`id: t\nname: x\nstep: a.step\ncolours: {default: teal}\n${pin}`), /palette/);
  });
  test('errors are SpecError', () => {
    assert.throws(load(`id: t\nname: x\nstep: a.step\npins: []`), SpecError);
  });
});
